/**
 * 修改后台登录页面LOGO的图标、链接及标题;
 */
// 修改LOGO图标
function logo_login_head() { 
    echo '<style type="text/css">#backtoblog,#nav{display:none;}#login h1 a{background-image:none,url(data:image/png;base64,);}</style>';
}
add_action('login_head', 'logo_login_head');
// 修改LOGO的链接
add_filter('login_headerurl',create_function(false,"return get_bloginfo('siteurl');"));
// 修改LOGO的链接的标题
add_filter('login_headertitle',create_function(false,"return get_bloginfo('name');"));
